import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync, rmSync } from 'node:fs';
import { join, isAbsolute } from 'node:path';
import { AutoRAGAgent, defaultEmbeddingConfig, releaseEmbedders } from '/workspace/dist/index.js';

const phase = process.argv[2];
assert(['cold', 'warm', 'read'].includes(phase));
const root = '/qa-state';
const docs = join(root, 'documents');
const workspace = join(root, 'workspace');
const config = process.env.AUTORAG_CONFIG!;
assert(config.startsWith('/dev-home/'));
assert.equal(process.env.AUTORAG_HOME, '/dev-home/.autorag');
mkdirSync(docs, { recursive: true });
const source = join(docs, '退款规则-中文.txt');
if (phase === 'cold') {
    writeFileSync(source, '退款例外必须在付款前获得主管批准。');
    writeFileSync(join(docs, 'travel.txt'), 'International travel reimbursement requires an itemized hotel receipt.');
}
const embedding = defaultEmbeddingConfig();
embedding.profiles['local-qwen3'].manifest!.tokenizerPath = '/dev-home/.autorag/models/fastembed/qwen3-0.6b-af95f2c416ffe9379369ad64f9113e865db6112c';
const options = { searchPaths: [docs], workspacePath: workspace, memoryPath: join(root, 'memory.json'), embedding,
    jikji: false, everything: false, fsearch: false, dupey: false, filee: false, jev: false, webSearch: false };
const before = existsSync(config) ? createHash('sha256').update(readFileSync(config)).digest('hex') : 'ABSENT';
if (phase === 'cold') writeFileSync(config, JSON.stringify(options, null, 2));
else assert.equal(readFileSync(config, 'utf8'), JSON.stringify(options, null, 2));
const agent = new AutoRAGAgent(options);
const ready = join(workspace, '.autorag/local-index/ready.json');
async function wait(jobId: string) {
    const deadline = Date.now() + 180_000;
    while (Date.now() < deadline) {
        const job = agent.indexJobs.status(jobId)!;
        if (['succeeded', 'failed', 'cancelled', 'interrupted'].includes(job.state)) {
            assert.equal(job.state, 'succeeded', job.error);
            return job;
        }
        await new Promise(resolve => setTimeout(resolve, 100));
    }
    throw new Error('Index task timeout');
}
async function query() {
    const results = await agent.getRetrievalEngine().retrieveSelected('退款例外需要谁批准？', { methods: ['local-vector'], local: true }, { topK: 5 });
    assert(results.results.some(hit => hit.source === source));
    for (const hit of results.results) { assert(isAbsolute(hit.source)); readFileSync(hit.source); }
}
const evidence: Record<string, unknown> = { phase, configPath: config, model: 'Qwen/Qwen3-Embedding-0.6B', dimension: 1024 };
try {
    if (phase === 'cold') {
        evidence.build = await wait(agent.startIndexJob({ mode: 'build' }).jobId);
        await query();
        writeFileSync(join(root, 'ready-before.json'), readFileSync(ready));
        evidence.configHash = createHash('sha256').update(readFileSync(config)).digest('hex');
    } else if (phase === 'warm') {
        assert.equal(readFileSync(ready, 'utf8'), readFileSync(join(root, 'ready-before.json'), 'utf8'));
        await query();
        evidence.queryBeforeRefresh = 'PASS';
        const unchanged = await wait(agent.startIndexJob({ mode: 'refresh' }).jobId);
        assert.equal(unchanged.report?.embedded, 0);
        evidence.unchanged = unchanged;
        writeFileSync(source, '退款例外必须在付款前获得主管批准。财务部门核对批准记录。');
        const increment = await wait(agent.startIndexJob({ mode: 'refresh' }).jobId);
        assert.equal(increment.report?.embedded, 1);
        evidence.increment = increment;
        rmSync(join(docs, 'travel.txt'));
        const deletion = await wait(agent.startIndexJob({ mode: 'refresh' }).jobId);
        assert.equal(deletion.report?.deleted, 1);
        evidence.deletion = deletion;
        await query();
        evidence.configUnchanged = before === createHash('sha256').update(readFileSync(config)).digest('hex');
        assert.equal(evidence.configUnchanged, true);
    } else {
        assert.equal(readFileSync(ready, 'utf8'), readFileSync(join(root, 'ready-before.json'), 'utf8'));
        await query();
        evidence.queryWithoutNetwork = 'PASS';
    }
    evidence.result = 'PASS';
} finally {
    await agent.indexJobs.close();
    await releaseEmbedders();
    writeFileSync('/qa-evidence/persistence-' + phase + '.json', JSON.stringify(evidence, null, 2));
}
console.log(JSON.stringify({phase, result: evidence.result, querySource: source}));
